import re

def split_fields(line):
    def replace_doubled_quotes(match):
        return match.group(1) + '"' + match.group(2)

    tokens = re.split(r',(?=(?:[^"]*"[^"]*")*[^"]*$)', line)
    result = []
    for token in tokens:
        token = token.strip()
        if token.startswith('"') and token.endswith('"'):
            token = token[1:-1]
            token = re.sub(r'""', replace_doubled_quotes, token)
        result.append(token)
    return result
